<?php require_once __DIR__.'/lib/inicio.php';if(usuario())ir('panel.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{validar_token();$s=bd()->prepare('SELECT u.*,d.numero_distrito FROM usuarios u LEFT JOIN distritos d ON d.id_distrito=u.id_distrito WHERE u.nombre_usuario=? AND u.activo=1');$s->bind_param('s',$_POST['usuario']);$s->execute();$u=$s->get_result()->fetch_assoc();if(!$u||!password_verify($_POST['clave'],$u['clave_hash']))throw new RuntimeException('Usuario o contraseña incorrectos.');unset($u['clave_hash']);$_SESSION['usuario']=$u;bitacora('INICIO_SESION');ir('panel.php');}catch(Throwable $e){$error=$e->getMessage();}}?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Acceso SCCMGPC</title><link rel="stylesheet" href="public/css/estilos.css"></head><body><div class="login"><div class="tarjeta"><div class="marca"><div class="simbolo">IECM</div><div><strong>SCCMGPC 2028</strong><small>Casos de actualización</small></div></div><h1>Inicio de sesión</h1><?php if($error):?><div class="aviso error"><?=h($error)?></div><?php endif?><form method="post"><input type="hidden" name="token" value="<?=token()?>"><label>Usuario</label><input name="usuario" required autocomplete="username"><label>Contraseña</label><input type="password" name="clave" required autocomplete="current-password"><button class="boton">Ingresar</button></form></div></div></body></html>